jsxGraph.script:
board.suspendUpdate();
var pP = board.create('point', [2, -3], {size: 3, color: 'black', name: 'P(2, -3)', withLabel: true, label: {autoPosition: false, offset: [-15, -15]}});
var pQ = board.create('point', [4, 5], {size: 3, color: 'black', name: 'Q(4, 5)', withLabel: true, label: {autoPosition: false, offset: [-10, 15]}});
var pR = board.create('point', [8, -1], {size: 3, color: 'black', name: 'R(8, -1)', withLabel: true, label: {autoPosition: false, offset: [15, 10]}});
board.create('polygon', [pP, pQ, pR], {fillColor: 'none', borders: {strokeColor: 'black', strokeWidth: 1.5}});
var pS = board.create('point', [3, 1], {size: 3, color: 'blue', name: 'S(3, 1)', withLabel: true, label: {autoPosition: false, offset: [-15, 10]}});
board.create('segment', [pS, pR], {strokeColor: 'blue', strokeWidth: 1});
board.unsuspendUpdate();
